return ['domain'=>'publishpress-authors&& n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 08:07+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'يتيح لك PublishPress Authors إضافة مؤلفين متعددين ومؤلفين ضيوف إلى منشورات WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'ترقية إلى النسخة المحترفة','This plugin can be deleted.'=>'يمكن حذف هذه الإضافة.','Actions provided by PublishPress plugins.'=>'الإجراءات المقدمة من إضافات PublishPress.','List Authors'=>'قائمة المؤلفين','Lists PublishPress Authors. Results never include author email addresses.'=>'تدرج PublishPress Authors. النتائج لا تتضمن أبدًا عناوين البريد الإلكتروني للمؤلفين.','Get Author'=>'احصل على المؤلف','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'يحصل على مؤلف PublishPress واحد بواسطة معرف المصطلح. الاستجابة لا تتضمن أبدًا عنوان البريد الإلكتروني.','Get Post Authors'=>'احصل على مؤلفي المنشور','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'يحصل على مؤلفي PublishPress المرتبين والمعينين لمنشور قابل للتعديل واحد. الاستجابة لا تتضمن أبدًا عناوين البريد الإلكتروني للمؤلفين.','Get Author Fields'=>'احصل على حقول المؤلف','Lists enabled author-profile field definitions without exposing profile values.'=>'تدرج تعريفات حقول ملف تعريف المؤلف المفعلة دون الكشف عن قيم الملف الشخصي.','Author not found.'=>'المؤلف غير